<template><div class="page"><div class="page-header"><h2>工单工序</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="wo_id" label="工单编号" width="110"/><el-table-column prop="process_cd" label="工序编码" width="100"/><el-table-column prop="seq_no" label="序号" width="60"/><el-table-column label="计划数" width="80"><template #default="{row}">{{ row.plan_qty||0 }}</template></el-table-column><el-table-column label="完成数" width="80"><template #default="{row}">{{ row.actual_qty||0 }}</template></el-table-column><el-table-column label="不良品" width="80"><template #default="{row}">{{ row.defect_qty||0 }}</template></el-table-column><el-table-column label="状态" width="80"><template #default="{row}"><el-tag :type="wpStatusTag(row.status)" size="small">{{ row.status||'PENDING' }}</el-tag></template></el-table-column><el-table-column prop="worker_cd" label="操作工" width="80"/></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'工单工序详情'" v-model="drawer" width="500px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="工单编号">{{ detail.wo_id }}</el-descriptions-item><el-descriptions-item label="工序编码">{{ detail.process_cd||'-' }}</el-descriptions-item><el-descriptions-item label="序号">{{ detail.seq_no }}</el-descriptions-item><el-descriptions-item label="状态"><el-tag :type="wpStatusTag(detail.status)" size="small">{{ detail.status||'PENDING' }}</el-tag></el-descriptions-item><el-descriptions-item label="计划数">{{ detail.plan_qty||0 }}</el-descriptions-item><el-descriptions-item label="完成数">{{ detail.actual_qty||0 }}</el-descriptions-item><el-descriptions-item label="不良品">{{ detail.defect_qty||0 }}</el-descriptions-item><el-descriptions-item label="操作工">{{ detail.worker_cd||'-' }}</el-descriptions-item><el-descriptions-item label="开始时间">{{ detail.start_time||'-' }}</el-descriptions-item><el-descriptions-item label="结束时间">{{ detail.end_time||'-' }}</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{ detail.remark||'-' }}</el-descriptions-item></el-descriptions></template></el-dialog></div></template>
<script setup lang="ts">import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {fetchWorkProcesses} from '@/api/mes';import type {MesRecord} from '@/api/mes'
const{items,loading,page,perPage,total}=useListPage<MesRecord>((p?:Record<string,string>)=>fetchWorkProcesses(p?.wo_id||'',p));const{drawer,detail,open}=useDetailDrawer<MesRecord>()
function wpStatusTag(s:string){const m:Record<string,string>={PENDING:'info',IN_PROGRESS:'warning',COMPLETED:'success',SKIPPED:'info'};return m[s]||'info'}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}</style>
